package main

import (
	"crypto/hmac"
	"crypto/sha256"
	"encoding/binary"
	"encoding/hex"
	"fmt"
	"io"
	"log"
	"net/http"
	"os"
	"sync"
)

// SecureBuffer provides authenticated read access to shared memory regions
type SecureBuffer struct {
	mu   sync.RWMutex
	data []byte
	key  []byte
}

func NewSecureBuffer(data []byte, key []byte) *SecureBuffer {
	return &SecureBuffer{data: data, key: key}
}

// verifyMAC checks the HMAC-SHA256 of the request parameters
func (sb *SecureBuffer) verifyMAC(offset, size int, providedMAC string) bool {
	mac := hmac.New(sha256.New, sb.key)
	params := fmt.Sprintf("%d:%d", offset, size)
	mac.Write([]byte(params))
	expectedMAC := hex.EncodeToString(mac.Sum(nil))
	return hmac.Equal([]byte(expectedMAC), []byte(providedMAC))
}

// ReadRegion returns a slice of the buffer after bounds validation
// Both offset and size are validated to prevent out-of-bounds access
func (sb *SecureBuffer) ReadRegion(offset, size int) ([]byte, error) {
	sb.mu.RLock()
	defer sb.mu.RUnlock()

	// Validate offset is non-negative
	if offset < 0 {
		return nil, fmt.Errorf("invalid offset: must be non-negative")
	}

	// Validate size is positive
	if size <= 0 {
		return nil, fmt.Errorf("invalid size: must be positive")
	}

	// Bounds check: ensure offset + size doesn't exceed buffer length
	if offset+size <= len(sb.data) {
		return sb.data[offset : offset+size], nil
	}

	return nil, fmt.Errorf("read would exceed buffer bounds")
}

func (sb *SecureBuffer) handleRead(w http.ResponseWriter, r *http.Request) {
	if r.Method != http.MethodPost {
		http.Error(w, "method not allowed", http.StatusMethodNotAllowed)
		return
	}

	// Parse binary request: 8 bytes offset + 8 bytes size + 64 bytes hex MAC
	body, err := io.ReadAll(io.LimitReader(r.Body, 80))
	if err != nil || len(body) < 80 {
		http.Error(w, "invalid request format", http.StatusBadRequest)
		return
	}

	offset := int(binary.BigEndian.Uint64(body[0:8]))
	size := int(binary.BigEndian.Uint64(body[8:16]))
	providedMAC := string(body[16:80])

	// Verify request authenticity
	if !sb.verifyMAC(offset, size, providedMAC) {
		http.Error(w, "authentication failed", http.StatusForbidden)
		return
	}

	// Read the authenticated region
	region, err := sb.ReadRegion(offset, size)
	if err != nil {
		http.Error(w, err.Error(), http.StatusBadRequest)
		return
	}

	w.Header().Set("Content-Type", "application/octet-stream")
	w.Write(region)
}

func main() {
	secret := os.Getenv("HMAC_SECRET")
	if len(secret) < 32 {
		log.Fatal("HMAC_SECRET must be at least 32 bytes")
	}

	// Initialize buffer with sensitive data
	sensitiveData := make([]byte, 4096)
	copy(sensitiveData, []byte("PUBLIC_REGION_DATA_HERE"))
	copy(sensitiveData[2048:], []byte("PRIVATE_SECRET_KEY_MATERIAL"))

	buf := NewSecureBuffer(sensitiveData, []byte(secret))

	http.HandleFunc("/read", buf.handleRead)
	log.Printf("Listening on :8080")
	log.Fatal(http.ListenAndServe(":8080", nil))
}
